import {allowedActions} from './constraints.mjs';
export function chooseRules(o,memory={}) {
 const allowed=allowedActions(o);if(!allowed.length)throw Error('terminal');
 let recovering=!!memory.recovering;
 if(o.pressure!==null){if(o.pressure>o.target[1]||o.health<=4)recovering=true;if(o.pressure<o.target[0]&&o.health>=7)recovering=false;}
 if(o.pressure===null)recovering=o.health<=4;
 let kind='rest';
 if(!recovering)kind=allowed.includes('brute')&&o.health>=10?'brute':allowed.includes('swarm')&&o.health>=8?'swarm':allowed.includes('scout')?'scout':'rest';
 return {action:{kind},memory:{recovering},reason:recovering?'recovery':'challenge',origin:'rules'};
}

