import {canonical,hash,distributionOK} from '../shared.mjs';
export function buildRequest(observation,allowed,config={model:'fixture-v1',host:'offline'}) {
 if(!allowed.length||new Set(allowed).size!==allowed.length)throw Error('invalid allowed set');
 const question={type:'choice',instructions:'Choose the next encounter to reach charge 12 by round 12 while respecting the announced pressure target. Use only available public observations.',criteria:Object.fromEntries(allowed.map(k=>[k,k==='rest'?'Restore health and supplies without charge.':`Offer a ${k} encounter.`]))};
 const body={model:config.model,state:canonical(observation),questions:{encounter:question}};
 const binding={stateHash:hash(observation),questionHash:hash(question),episodeId:observation.episodeId,revision:observation.revision,allowed:[...allowed],model:config.model,host:config.host,adapterVersion:'beacon-adapter/1'};
 binding.requestId=hash({body,binding});return {body,binding};
}
export function parseResponse(raw,request,current,origin='synthetic-fixture') {
 const b=request.binding;
 if(hash(current)!==b.stateHash||current.episodeId!==b.episodeId||current.revision!==b.revision)return {ok:false,error:'stale'};
 if(hash(request.body.questions.encounter)!==b.questionHash||hash({body:request.body,binding:Object.fromEntries(Object.entries(b).filter(([k])=>k!=='requestId'))})!==b.requestId)return {ok:false,error:'invalid-binding'};
 const answer=raw?.answers?.encounter;
 if(raw?.model!==b.model||answer?.type!=='choice'||!b.allowed.includes(answer.choice)||!distributionOK(answer.probabilities,b.allowed)||!Number.isFinite(answer.confidence)||answer.confidence<0||answer.confidence>1)return {ok:false,error:'invalid-response'};
 return {ok:true,action:{kind:answer.choice},distribution:answer.probabilities,score:answer.confidence,binding:{...b},origin};
}
